export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',training:'M4 8v8m3-10v12m10-12v12m3-10v8M7 12h10',exercises:'M4 4h16v16H4zM8 8h8M8 12h8M8 16h4',anatomy:'M12 3a2 2 0 1 0 0 4a2 2 0 1 0 0-4M5 10l7-2l7 2M12 8v6m0 0l-4 7m4-7l4 7',body:'M5 5h14v16H5zM9 5V3h6v2m-6 5h6',calories:'M8 3h8v4l4 5v9H4v-9l4-5V3m0 4h8M8 15h8',cardio:'M3 12h4l3-7l4 14l3-7h4',plan:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16M8 14h2m4 0h2',insights:'M4 20V10m8 10V4m8 16v-7M2 20h20',evidence:'M3 4h7l2 2l2-2h7v16h-7l-2 2l-2-2H3V4m9 2v16',settings:'M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8M9 3h6l1 3l3 1l2 5l-2 5l-3 1l-1 3H9l-1-3l-3-1l-2-5l2-5l3-1z',plus:'M12 5v14M5 12h14',close:'M6 6l12 12M18 6L6 18',menu:'M4 6h16M4 12h16M4 18h16',moon:'M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10',sun:'M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12l1 1M5 19l1-1M18 6l1-1',weight:'M6 8h12l3 13H3L6 8m3 0V6a3 3 0 0 1 6 0v2',check:'M5 12l4 4L19 6',time:'M12 8v4l3 2M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18',download:'M12 3v12m-5-5l5 5l5-5M4 17v4h16v-4',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5z',search:'M10 3a7 7 0 1 0 0 14a7 7 0 1 0 0-14m5 12l6 6'};
export const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.check}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
export const btn=(label,action,cls='',ico='')=>`<button class="btn ${cls}" data-action="${esc(action)}">${ico?icon(ico):''}${esc(label)}</button>`;
export const empty=(title,description,action='',label='')=>`<div class="empty"><strong>${esc(title)}</strong><p>${esc(description)}</p>${action?btn(label,action,'small'):''}</div>`;
export const field=(name,label,value='',type='text',attrs='',help='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}>${help?`<small>${help}</small>`:''}</div>`;
export const select=(name,label,value,options,help='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option value="${esc(Array.isArray(o)?o[0]:o)}" ${value===(Array.isArray(o)?o[0]:o)?'selected':''}>${esc(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</div>`;
export const num=(v,d=0)=>Number.isFinite(Number(v))&&v!==null&&v!==''?Number(v).toLocaleString(undefined,{maximumFractionDigits:d}):'—';
export const dateLabel=(s,options={month:'short',day:'numeric'})=>new Date(s+'T12:00:00').toLocaleDateString(undefined,options);
export const metric=(title,value,unit,foot,ico)=>`<div class="card metric"><div class="metric-title">${esc(title)}${icon(ico)}</div><div class="metric-value mono">${value}<span>${esc(unit)}</span></div><div class="metric-foot">${esc(foot)}</div></div>`;
export function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4000)}
export function modal(title,body,onSubmit){const d=document.querySelector('#modal');d.innerHTML=`<div class="modal-header"><h2>${esc(title)}</h2><button class="btn ghost small" data-close aria-label="Close dialog">${icon('close')}</button></div><form class="modal-body">${body}<p class="error" role="alert"></p><div class="modal-footer"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">Save</button></div></form>`;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await onSubmit(new FormData(e.target),e.target);d.close()}catch(err){d.querySelector('.error').textContent=err.message}finally{b.disabled=false}};if(!d.open)d.showModal();return d}
export function chart(points,{unit='',secondary=null,height=230,color=null,bars=false}={}){if(!points.length)return empty('Your trend starts here','Log a few entries to see how your progress changes over time.');const w=640,h=height,p={l:48,r:16,t:20,b:35};const vals=points.map(x=>x.value).concat(secondary?.map(x=>x.value)||[]);let lo=Math.min(...vals),hi=Math.max(...vals);if(bars)lo=0;const span=hi-lo||Math.max(1,hi*.02);lo=bars?0:lo-span*.15;hi+=span*.15;const dates=points.map(x=>Date.parse(x.date+"T12:00:00Z")),first=Math.min(...dates),last=Math.max(...dates);const xx=i=>p.l+(dates[i]-first)*(w-p.l-p.r)/Math.max(86400000,last-first),yy=v=>h-p.b-(v-lo)/(hi-lo)*(h-p.t-p.b);const path=arr=>arr.map((v,i)=>(i?'L':'M')+xx(i)+','+yy(v.value)).join(' ');const ticks=Array.from({length:4},(_,i)=>lo+(hi-lo)*i/3);return `<svg viewBox="0 0 ${w} ${h}" class="chart" role="img" aria-label="${esc(unit)} history from ${esc(points[0].date)} to ${esc(points.at(-1).date)}">${ticks.map(v=>`<path class="gridline" d="M${p.l} ${yy(v)}H${w-p.r}"/><text x="${p.l-8}" y="${yy(v)+4}" text-anchor="end">${num(v,1)}</text>`).join('')}${secondary?`<path class="secondary" d="${path(secondary)}"/>`:''}${bars?points.map((v,i)=>`<rect class="bar" x="${xx(i)-Math.min(8,180/points.length)}" y="${yy(v.value)}" width="${Math.min(16,360/points.length)}" height="${h-p.b-yy(v.value)}"><title>${esc(v.date)}: ${num(v.value,1)} ${esc(unit)}</title></rect>`).join(''):`<path class="line" ${color?`style="stroke:${color}"`:''} d="${path(points)}"/>${points.map((v,i)=>`<circle class="point" cx="${xx(i)}" cy="${yy(v.value)}" r="3"><title>${esc(v.date)}: ${num(v.value,2)} ${esc(unit)}</title></circle>`).join('')}`}<text x="${p.l}" y="${h-5}">${dateLabel(points[0].date)}</text><text x="${w-p.r}" y="${h-5}" text-anchor="end">${dateLabel(points.at(-1).date)}</text></svg><details class="chart-details"><summary>Inspect chart data</summary><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>${esc(unit||'Value')}</th></tr></thead><tbody>${points.map(p=>`<tr><td>${esc(p.date)}</td><td>${num(p.value,2)}</td></tr>`).join('')}</tbody></table></div></details>`}
